function mMidi(n){const m=/^([A-G])(#|b)?(\d)$/.exec(n);if(!m)return 60;const base={C:0,D:2,E:4,F:5,G:7,A:9,B:11}[m[1]];return 12*(Number(m[3])+1)+base+(m[2]==='#'?1:m[2]==='b'?-1:0)}
