   if(bt==='walk'){if(i%2===0){const k=i/2;e.bass={m:root+[0,0,7,0,12,0,7,0][k],len:2}}}
   else if(bt==='drive'){e.bass={m:root+(i%4===2?12:0),len:1}}
   else if(bt==='gallop'){if(i%4!==3)e.bass={m:root+(i%8===6?7:0),len:1}}
   else if(bt==='half'){if(i===0)e.bass={m:root,len:8};else if(i===8)e.bass={m:root+7,len:8}}
   const aM=(d.sweepFrom!=null&&b>=d.sweepFrom)?'sweep':(d.arpFrom!=null&&b<d.arpFrom)?'off':d.arpMode;if(aM==='off'){}else if(aM==='flow'){if(i%2===0){const pool=[tones[0],tones[1],tones[2],tones[0]+12],sq=[0,1,2,3,2,1,2,1];e.arp={m:pool[sq[((i/2)|0)%8]],len:2}}}else if(aM==='sweep'){const ix=i%8;e.arp={m:tones[ix%3]+12*(1+((ix/3)|0)),len:1}}else if(d.arp){const step=d.bass==='half'?2:1;if(i%step===0){e.arp={m:tones[((i/step)|0)%3]+12,len:step}}}
   if(d.drums==='soft'&&(d.drumsFrom==null||b>=d.drumsFrom)){if(i===0||i===8)e.kick=true;if(i===4||i===12)e.snare=true;if(i%4===2)e.hat=true}
