function musicSchedule(A,out,step,t,data){
 const e=data.ev[step],sd=60/data.bpm/4,def=MUSIC_DEFS[musicTrack],i=step%16,bar=(step/16)|0,battle=def&&(def.drums==='battle'||def.drums==='boss');
 if(e.lead){const f=mFreq(e.lead.m),d=Math.max(.07,sd*e.lead.len*.94);musLead(A,out,t,f,d,.05*(def&&def.crescendo?(.6+.8*bar/Math.max(1,data.total/16-1)):1));if((battle||musicTrack==='evolution')&&e.lead.len>=2)musLead(A,out,t+sd*3,f,Math.max(.06,d*.7),.012)}
 if(e.bass){const f=mFreq(e.bass.m);chipTone(A,out,t,f,f,0,Math.max(.05,sd*e.bass.len*.78),'triangle',(def&&def.bassVol||.085));chipTone(A,out,t,f*2,f*2,0,.07,'pulse25',.016)}
 if(e.arp){const cr=def&&def.crescendo?(.55+.9*bar/Math.max(1,data.total/16-1)):1;chipTone(A,out,t,mFreq(e.arp.m),mFreq(e.arp.m),0,Math.max(.04,sd*e.arp.len*.55),def&&(def.arpMode==='sweep'||def.arpMode==='flow')?'pulse25':'sawtooth',(def&&def.arpVol||.014)*cr)}
 if(e.kick){chipTone(A,out,t,200,40,0,.14,'triangle',.15);chipNoiseHit(A,out,t,900,300,0,.02,.04,1,'lowpass')}
 let sn=e.snare;if(battle&&bar===7&&i>=12)sn=true;
 if(sn){chipNoiseHit(A,out,t,2600,700,0,.12,.07,1,'bandpass');chipTone(A,out,t,200,120,0,.05,'triangle',.05)}
 if(e.hat){const open=battle&&i%8===6;chipNoiseHit(A,out,t,7500,7000,0,open?.09:.03,open?.022:.016,1,'highpass')}
}
function musicStop(fade=.25){
 if(musicTimer){clearInterval(musicTimer);musicTimer=null}
 if(musicOut&&audioCtx){const g=musicOut,A=audioCtx;try{g.gain.cancelScheduledValues(A.currentTime);g.gain.setValueAtTime(g.gain.value,A.currentTime);g.gain.linearRampToValueAtTime(.0001,A.currentTime+fade);setTimeout(()=>{try{g.disconnect()}catch(e){}},fade*1000+120)}catch(e){}}
 musicOut=null;musicTrack=null;
}
function musicStart(name){
 if(!musicOn||!MUSIC_DEFS[name])return;
 if(musicTrack===name&&musicTimer)return;
 const A=musicCtx();if(!A)return;
 musicStop(.3);
 const data=musicCompile(name);musicData=data;musicTrack=name;
 const out=A.createGain();out.gain.setValueAtTime(.0001,A.currentTime);out.gain.linearRampToValueAtTime(.55*musicDuck,A.currentTime+.4);out.connect(A.destination);musicOut=out;
 musicStep=0;musicNextTime=A.currentTime+.08;
 const sd=60/data.bpm/4;
 musicTimer=setInterval(()=>{
  if(!musicOut||!audioCtx)return;
  if(musicNextTime<A.currentTime-.4)musicNextTime=A.currentTime+.05;
  while(musicNextTime<A.currentTime+.15){musicSchedule(A,musicOut,musicStep,musicNextTime,data);musicNextTime+=sd;musicStep=(musicStep+1)%data.total}
 },30);
}
